/* Product vision, requirements, architecture direction and delivery leadership: Andrews Mensah. */
const status=document.querySelector('#design-status'),screenSelect=document.querySelector('#screen-select');
const labels={insurance:'Insurance & benefits',insured:'Insured patient estimate',selfpay:'Self-pay patient estimate',overview:'Overview',crm:'Patient workspace',plans:'Treatment plans',quotes:'Pricing intelligence',finance:'Financing',evidence:'AI & governance',status:'Project details',approvals:'Approval center',executive:'Executive workspace',clinical:'Clinician workspace',nursing:'Nursing & coordination',patient:'Patient care workspace',reviewer:'Pricing reviewer workspace'};
let snapshots={},current='overview',saved={};
try{saved=JSON.parse(localStorage.getItem('clarity-grapes-layouts-v3-insurance')||'{}');}catch{}
try{const response=await fetch('design-screens.json');if(response.ok)snapshots=await response.json();}catch{}
try{const seed=JSON.parse(sessionStorage.getItem('clarity-design-seed'));if(seed?.version==='role-workspaces-v1'&&seed?.html&&labels[seed.page]){snapshots[seed.page]={html:seed.html};current=seed.page;}}catch{}
const applicationCss=await fetch('styles.css').then(r=>r.text());
const fallback='<main style="padding:50px;background:#f5f7fa;font-family:Arial"><h1>Clarity Dental</h1><p>Open a screen in the Live prototype, then choose Design studio to edit its layout.</p></main>';
if(!window.grapesjs){status.textContent='Editor assets could not load. Run npm ci and npm run vendor.';throw Error('GrapesJS assets unavailable');}
const editor=window.grapesjs.init({container:'#gjs',height:'calc(100vh - 142px)',width:'auto',components:snapshots[current]?.html||fallback,storageManager:false,telemetry:false,panels:{defaults:[]},canvas:{styles:['styles.css']},parser:{optionsHtml:{allowScripts:false,allowUnsafeAttr:false,allowUnsafeAttrValue:false}},layerManager:{appendTo:'#layers'},blockManager:{appendTo:'#blocks',blocks:[{id:'clarity-card',label:'Decision card',content:'<section class="panel"><h2>Decision summary</h2><p class="small">Explain the next step clearly.</p><a class="button" href="#quotes">View estimate</a></section>'},{id:'clarity-metric',label:'Metric',content:'<div class="stat"><div class="stat-top">Workspace metric</div><b>0</b><div class="stat-foot">Define the measure</div></div>'},{id:'clarity-note',label:'Insight',content:'<div class="insight-callout"><div><strong>A clear insight</strong><p>Turn the evidence into a helpful next step.</p></div></div>'},{id:'clarity-heading',label:'Heading',content:'<div class="page-heading"><div><div class="eyebrow">CLARITY DENTAL</div><h1>A confident next step.</h1><p class="sub">Designed around the patient journey.</p></div></div>'}]},styleManager:{appendTo:'#styles',sectors:[{name:'Layout',open:true,buildProps:['display','width','height','padding','margin','gap']},{name:'Typography',open:false,buildProps:['font-family','font-size','font-weight','line-height','letter-spacing','color','text-align']},{name:'Surface',open:false,buildProps:['background-color','border','border-radius','box-shadow','opacity']}]},traitManager:{appendTo:'#traits'},deviceManager:{devices:[{id:'Desktop',name:'Desktop',width:''},{id:'Tablet',name:'Tablet',width:'820px',widthMedia:'900px'},{id:'Mobile',name:'Mobile',width:'390px',widthMedia:'650px'}]}});
window.clarityEditor=editor;
screenSelect.innerHTML=Object.entries(labels).map(([id,label])=>`<option value="${id}" ${id===current?'selected':''}>${label}</option>`).join('');
const setTitle=()=>document.querySelector('#canvas-title').textContent=`${labels[current]} / editable canvas`;
const loadCurrent=()=>{if(saved[current])editor.loadProjectData(saved[current]);else editor.setComponents(snapshots[current]?.html||fallback);setTitle();status.textContent='Ready · select a layer or double-click text to edit';};
editor.on('load',loadCurrent);editor.on('update',()=>status.textContent='Unsaved layout changes');setTitle();
screenSelect.addEventListener('change',()=>{saved[current]=editor.getProjectData();current=screenSelect.value;loadCurrent();});
document.querySelectorAll('[data-device]').forEach(b=>b.addEventListener('click',()=>{editor.setDevice(b.dataset.device);document.querySelectorAll('[data-device]').forEach(x=>x.classList.toggle('active',x===b));status.textContent=`${b.dataset.device} canvas preview`;}));
document.querySelectorAll('[data-left-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.left-tab').forEach(x=>x.hidden=x.id!==b.dataset.leftTab);document.querySelectorAll('[data-left-tab]').forEach(x=>x.classList.toggle('active',x===b));}));
document.querySelector('#undo').onclick=()=>editor.UndoManager.undo();document.querySelector('#redo').onclick=()=>editor.UndoManager.redo();
document.querySelector('#save-layout').onclick=()=>{try{saved[current]=editor.getProjectData();localStorage.setItem('clarity-grapes-layouts-v3-insurance',JSON.stringify(saved));status.textContent='Layout saved on this device';}catch{status.textContent='Storage is unavailable; export the project JSON to keep your changes.';}};
function download(name,type,content){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent=`Exported ${name}`;}
document.querySelector('#export-project').onclick=()=>download(`clarity-${current}-design.json`,'application/json',JSON.stringify({creator:'Andrews Mensah',tool:'GrapesJS',screen:current,project:editor.getProjectData()},null,2));
document.querySelector('#export-html').onclick=()=>download(`clarity-${current}-design.html`,'text/html',`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clarity Dental design — Andrews Mensah</title><style>${applicationCss}</style><style>${editor.getCss()}</style></head><body>${editor.getHtml()}</body></html>`);
document.querySelector('#import-project').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Choose a project JSON under 2 MB');const data=JSON.parse(await file.text());if(!data.project||!Array.isArray(data.project.pages))throw Error('Choose a Clarity design project export');editor.loadProjectData(data.project);status.textContent='Imported editable project';}catch(error){status.textContent=error.message;}e.target.value='';};
